import java.util.*;

class LRUCache {
    private final int capacity;
    private final Map<Integer, Integer> map;
    private final List<Integer> order;   // 末尾最新，开头最老

    public LRUCache(int capacity) {
        this.capacity = capacity;
        this.map = new HashMap<>();
        this.order = new ArrayList<>();
    }

    public int get(int key) {
        if (!map.containsKey(key)) return -1;
        // 挪到末尾标记为最近使用，这一步是 O(n)
        order.remove(Integer.valueOf(key));
        order.add(key);
        return map.get(key);
    }

    public void put(int key, int value) {
        if (map.containsKey(key)) {
            map.put(key, value);
            order.remove(Integer.valueOf(key));
            order.add(key);
            return;
        }
        map.put(key, value);
        order.add(key);
        if (map.size() > capacity) {
            int oldest = order.remove(0);   // 最久没用的
            map.remove(oldest);
        }
    }
}

import java.util.*;

class LRUCache {
    private final int capacity;
    private final LinkedHashMap<Integer, Integer> map;

    public LRUCache(int capacity) {
        this.capacity = capacity;
        // 第三个参数 true = 按访问顺序排列，get 会自动把键挪到末尾
        this.map = new LinkedHashMap<>(capacity, 0.75f, true);
    }

    public int get(int key) {
        // 必须用 get 而不是 getOrDefault！后者不触发 afterNodeAccess
        Integer v = map.get(key);
        return v == null ? -1 : v;
    }

    public void put(int key, int value) {
        map.put(key, value);
        if (map.size() > capacity) {
            // 链表头就是最久没被访问的键
            Iterator<Integer> it = map.keySet().iterator();
            if (it.hasNext()) {
                it.next();
                it.remove();
            }
        }
    }
}

import java.util.*;

class LRUCache {
    private static class Node {
        int key, value;
        Node prev, next;
        Node(int k, int v) { key = k; value = v; }
    }

    private final int capacity;
    private final Map<Integer, Node> map;
    private final Node head, tail;   // 哨兵，省掉所有判空

    public LRUCache(int capacity) {
        this.capacity = capacity;
        this.map = new HashMap<>();
        this.head = new Node(0, 0);
        this.tail = new Node(0, 0);
        head.next = tail;
        tail.prev = head;
    }

    public int get(int key) {
        Node node = map.get(key);
        if (node == null) return -1;
        moveToHead(node);
        return node.value;
    }

    public void put(int key, int value) {
        Node node = map.get(key);
        if (node != null) {
            node.value = value;
            moveToHead(node);
            return;
        }
        if (map.size() == capacity) {
            Node oldest = tail.prev;   // tail 是哨兵，真正最老的是它的前驱
            remove(oldest);
            map.remove(oldest.key);    // 所以 Node 必须存 key
        }
        Node fresh = new Node(key, value);
        addFirst(fresh);
        map.put(key, fresh);
    }

    private void remove(Node node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    private void addFirst(Node node) {
        node.next = head.next;
        node.next.prev = node;
        head.next = node;
        node.prev = head;
    }

    private void moveToHead(Node node) {
        remove(node);
        addFirst(node);
    }
}
